class Solution {
    public int tallestBillboard(int[] rods) {
        java.util.Map<Integer, Integer> dp = new java.util.HashMap<>();
        dp.put(0, 0);
        for (int rod : rods) {
            java.util.Map<Integer, Integer> cur = new java.util.HashMap<>(dp);
            for (var e : cur.entrySet()) {
                int diff = e.getKey(), tall = e.getValue();
                dp.merge(diff + rod, tall + rod, Math::max);
                dp.merge(diff - rod, tall, Math::max);
            }
        }
        return dp.getOrDefault(0, 0);
    }
}
